    def u1():return read(1)[0]
    def u2():return int.from_bytes(read(2),'big')
    def u4():return int.from_bytes(read(4),'big')
    assert read(4)==b'\xca\xfe\xba\xbe';minor=u2();major=u2();count=u2();cp=[None]*count;i=1
    while i<count:
