        elif tag in [3,4]:cp[i]=(tag,read(4))
        elif tag in [5,6]:cp[i]=(tag,read(8));i+=1
        elif tag in [7,8,16,19,20]:cp[i]=(tag,u2())
        elif tag in [9,10,11,12,17,18]:cp[i]=(tag,u2(),u2())
        elif tag==15:cp[i]=(tag,u1(),u2())
