        i+=1
    def utf(index):return cp[index][1]
    def ref(index):
        item=cp[index]
        if item[0]==8:return {'string':utf(item[1])}
        if item[0] in [9,10,11]:
            cls=cp[item[1]][1];name,desc=cp[item[2]][1:]
            return {'owner':utf(cls),'name':utf(name),'descriptor':utf(desc)}
        return None
    access=u2();this=u2();parent=u2();interfaces=[u2() for _ in range(u2())]
    def attrs():
        return [(utf(u2()),read(u4())) for _ in range(u2())]
    for _ in range(u2()):read(6);attrs()
    methods=[]
    for _ in range(u2()):
        flags=u2();name=utf(u2());desc=utf(u2());attributes=attrs()
        code=next((a[1] for a in attributes if a[0]=='Code'),None)
        if code is not None:code=code[8:8+int.from_bytes(code[4:8],'big')]
        methods.append((name,desc,code))
