    return methods,ref


def instructions(code):
    i=0
    two=set([0x10,0x12,*range(0x15,0x1a),*range(0x36,0x3b),0xa9,0xbc])
    three=set([0x11,0x13,0x14,0x84,*range(0x99,0xa9),*range(0xb2,0xb9),0xbb,0xbd,0xc0,0xc1,0xc6,0xc7])
    while i<len(code):
        op=code[i];size=2 if op in two else 3 if op in three else 4 if op==0xc5 else 5 if op in [0xb9,0xba,0xc8,0xc9] else 1
        if op in [0xaa,0xab]:
            start=i+1+(4-(i+1)%4)%4
            if op==0xaa:
                low,high=struct.unpack('>ii',code[start+4:start+12]);size=start+12+4*(high-low+1)-i
            else:size=start+8+8*int.from_bytes(code[start+4:start+8],'big')-i
        elif op==0xc4:size=6 if code[i+1]==0x84 else 4
        assert size>0 and i+size<=len(code)
        yield i,op,code[i+1:i+size]
        i+=size
    assert i==len(code)


